import java.util.*;

class Solution {
    public int longestEqualSubarray(List<Integer> nums, int k) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < nums.size(); i++) {
            pos.computeIfAbsent(nums.get(i), key -> new ArrayList<>()).add(i);
        }
        int ans = 0;
        for (List<Integer> idxs : pos.values()) {
            int left = 0;
            for (int right = 0; right < idxs.size(); right++) {
                while ((idxs.get(right) - idxs.get(left) + 1) - (right - left + 1) > k) {
                    left++;
                }
                ans = Math.max(ans, right - left + 1);
            }
        }
        return ans;
    }
}

